  'chart.wave.title': 'Bankdrücken · Welle 8 → 6 Wdh. · +1 kg',
  'chart.gzcl.title': 'Kniebeuge als T1 · +2,5 kg · letzter Satz AMRAP',
  'chart.note.double1': 'obere Grenze → mehr Gewicht',
  'chart.note.repgoal1': 'genau 25 reicht nicht',
