  'einheit.g1.li2': '<b>Doelherhalingen</b> als getal (<span class="k">5</span>), bereik (<span class="k">8-12</span>) of met <span class="k">+</span> voor AMRAP (<span class="k">5+</span>, <span class="k">8-12+</span>).',
